pragma solidity 0.6.12;




contract SetUser is Ownable {
    IDiv2 public _iDiv2Contract = IDiv2(0x0);
    IDiv3 public _iDiv3Contract = IDiv3(0x0);

    function setIDiv2(address iDiv2Contract) public onlyOwner  {
        _iDiv2Contract = IDiv2(iDiv2Contract);
    }

    function setIDiv3(address iDiv3Contract) public onlyOwner  {
        _iDiv3Contract = IDiv3(iDiv3Contract);
    }

    function getUserOld(address account) external view returns (uint256,uint256,uint256,uint256,uint256) {
        return _iDiv2Contract.userInfo(account);
    }

    function getBalanceOld(address account) external view returns (uint256) {
        return _iDiv2Contract.balanceOf(account);
    }

    function setUsers(address[] memory addresUser,uint256 lastUpdateTime , uint256 rewardPerTokenStored,uint256 startTime,uint256 initReward) public onlyOwner {
        uint256 userRewardPerTokenPaidOld ;
        uint256 rewardsOld ;
        uint256 currentBuffrateOld;
        uint256 currentPowerOld;
        uint256 timeStampOld;
        uint256 amountOld;
        _iDiv3Contract.setInitValue(lastUpdateTime,rewardPerTokenStored,startTime,initReward);
        for (uint8 i = 0; i < addresUser.length; i++){
            (userRewardPerTokenPaidOld,rewardsOld,currentBuffrateOld,currentPowerOld,timeStampOld) =  _iDiv2Contract.userInfo(addresUser[i]);
            amountOld = _iDiv2Contract.balanceOf(addresUser[i]);
            _iDiv3Contract.setUser(addresUser[i],userRewardPerTokenPaidOld,rewardsOld,currentBuffrateOld,currentPowerOld,timeStampOld,amountOld);
        }
    }
}

